async (_request, response) => {
  try {
    const pool = getApplicationPool();
    // Use a 2-second timeout so a slow DB doesn't hold Cloud Run indefinitely
    const client = await pool.connect();
    try {
      await client.query("SELECT 1");
    } finally {
      client.release();
    }
    response.json({ success: true, status: "ready", checks: { database: "ok" } });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Unknown error";
    response.status(503).json({
      success: false,
      status: "not_ready",
      checks: { database: "unavailable" },
      // Only include the raw message in non-production to avoid leaking connection strings
      ...(process.env["NODE_ENV"] !== "production" ? { detail: message } : {}),
    });
  }
}

